/* eslint-disable react/no-multi-comp */
import * as React from 'react';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import {
  Box,
  CircularProgress,
  Grid,
  IconButton,
  InputAdornment,
  Stack,
  TextField,
  Typography,
  useMediaQuery,
  MenuItem,
} from '@mui/material';
import BusinessOutlinedIcon from '@mui/icons-material/BusinessOutlined';
import FieldHeader from '../../../components/FieldHeader';
import { theme } from '../../../theme';
import { useFormik } from 'formik';
import { useNewBranchMutation } from '../../posApi';
import { useNotifier } from '../../../core/Notifier';
import { HEADER_GRADIENT } from '../../../theme/appColors';
import { useTranslation } from 'react-i18next';
import { IBranchDetailsData } from '../../../core/Interface/branch.interface';
import { useMemo } from 'react';
import { uploadImage } from '../../../core/utils';
import Visibility from '@mui/icons-material/Visibility';
import VisibilityOff from '@mui/icons-material/VisibilityOff';

interface INewBranch {
  openModel?: boolean;
  title: string;
  handleCloseDialog: (close: boolean) => void;
  branchdata?: IBranchDetailsData;
}

const NewBranch = ({
  title,
  openModel = false,
  handleCloseDialog,
  branchdata,
}: INewBranch) => {
  const [open] = React.useState(openModel);
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const [newBranch, { isLoading }] = useNewBranchMutation();
  const { showErrorMessage, showMessage } = useNotifier();
  const { t } = useTranslation(['common', 'category', 'branchManage']);
  const buttonText = branchdata ? t('common:update') : t('common:create');
  const [showPassword, setShowPassword] = React.useState(false);

  const handleClose = () => {
    handleCloseDialog(false);
  };

  const [selectedImage, setSelectedImage] = React.useState<File | undefined>(
    undefined
  );
  const [isImageUploading, setIsImageUploading] = React.useState(false);

  const validateMobileNumber = (value: string) => {
    if (value.startsWith('0')) {
      const mobileRegex = /^[0-9]{10}$/;
      return mobileRegex.test(value);
    } else {
      const mobileRegex = /^[1-9]{9}$/;
      return mobileRegex.test(value);
    }
  };

  const validateEmail = (value: string) => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(value);
  };

  const formik = useFormik({
    initialValues: {
      code: branchdata?.code,
      name: branchdata?.name,
      headerText1: branchdata?.headerText1,
      headerText2: branchdata?.headerText2,
      headerText3: branchdata?.headerText3,
      footerText1: branchdata?.footerText1,
      footerText2: branchdata?.footerText2,
      footerText3: branchdata?.footerText3,
      mobile: branchdata?.mobile,
      email: branchdata?.email,
      reloadLoginMobile: branchdata?.reloadLoginMobile,
      reloadLoginPassword: branchdata?.reloadLoginPassword,
      id: branchdata?.id,
      logo: branchdata?.logo,
      printPaperSize: branchdata?.printPaperSize || '',
      noticeText: branchdata?.noticeText || '',
      totalCount: branchdata?.totalCount || '',
    },
    onSubmit: async (values) => {
      try {
        let logo: string | undefined = branchdata?.logo;

        if (selectedImage) {
          setIsImageUploading(true);
          //formData.append('imageUrl', selectedImage);
          logo = (await uploadImage(selectedImage)) || '';
          setIsImageUploading(false);
        }

        values.logo = logo;

        if (!validateMobileNumber(values.reloadLoginMobile || '')) {
          showErrorMessage('Mobile number should be valid.');
          return;
        }

        if (!validateEmail(values.email || '')) {
          showErrorMessage('Please enter a valid email address.');
          return;
        }

        const temData = {
          code: values?.code,
          name: values?.name,
          headerText1: values?.headerText1,
          headerText2: values?.headerText2,
          headerText3: values?.headerText3,
          footerText1: values?.footerText1,
          footerText2: values?.footerText2,
          footerText3: values?.footerText3,
          mobile: values?.mobile,
          email: values?.email,
          reloadLoginMobile: values?.reloadLoginMobile,
          reloadLoginPassword: values?.reloadLoginPassword,
          id: branchdata?.id,
          logo,
          printPaperSize: values?.printPaperSize,
          noticeText: values?.noticeText,
          totalCount: values?.totalCount,
        };
        if (!branchdata) {
          delete values.id;
        }

        const addBranchResponse = await newBranch(temData).unwrap();
        if (!addBranchResponse.status) {
          showErrorMessage(addBranchResponse.message);
        } else {
          showMessage(addBranchResponse.message);
          handleClose();
        }
      } catch (error) {
        showErrorMessage((error as Error).message);
      }
    },
  });

  const formValid = useMemo(() => {
    return formik.values.code === '' ||
      formik.values.code === undefined ||
      formik.values.name === '' ||
      formik.values.name === undefined ||
      formik.values.mobile === '' ||
      formik.values.mobile === undefined ||
      formik.values.email === '' ||
      formik.values.email === undefined ||
      (branchdata
        ? false
        : formik.values.reloadLoginPassword === '' ||
          formik.values.reloadLoginPassword === undefined) ||
      formik.values.reloadLoginMobile === '' ||
      formik.values.reloadLoginMobile === undefined
      ? false
      : true;
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [formik]);

  const handleImageChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;

    if (files && files.length > 0) {
      setSelectedImage(files[0]);
    } else {
      setSelectedImage(undefined);
    }
  };


  const printPaperSizeOptions = [
    { key: '80mm', value: '80mm' },
    { key: '58mm', value: '58mm' },
    { key: 'A4', value: 'A4' },
    { key: 'A5', value: 'A5' },
  ];

  return (
    <div>
      <form noValidate onSubmit={formik.handleSubmit}>
        <Dialog
          aria-describedby="alert-dialog-description"
          classes={{ paper: 'inherit' }}
          fullScreen={isMobile}
          fullWidth={isMobile}
          maxWidth="lg"
          open={open}
          PaperProps={{ sx: { borderRadius: isMobile ? 0 : '12px', overflow: 'hidden' } }}
        >
          <DialogTitle sx={{ p: 0 }}>
            <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
              <Stack alignItems="center" direction="row" spacing={1.5}>
                <Box sx={{ alignItems: 'center', background: 'rgba(255,255,255,0.15)', borderRadius: '8px', display: 'flex', height: 36, justifyContent: 'center', width: 36, flexShrink: 0 }}>
                  <BusinessOutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
                </Box>
                <Box>
                  <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>{title}</Typography>
                  <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>Create or edit branch</Typography>
                </Box>
              </Stack>
            </Box>
          </DialogTitle>
          <DialogContent
            sx={{ width: isMobile ? 'auto' : '40vw', px: 3, pt: 3, pb: 1 }}
          >
            <Box>
              <Grid container>
                <GridItem>
                  <FieldHeader title={t('category:title.name')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('category:title.name')}
                    size="small"
                    {...formik.getFieldProps('name')}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('category:title.code')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('category:title.code')}
                    size="small"
                    {...formik.getFieldProps('code')}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('branchManage:mobile')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('branchManage:mobile')}
                    size="small"
                    {...formik.getFieldProps('mobile')}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('branchManage:email')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('branchManage:email')}
                    size="small"
                    {...formik.getFieldProps('email')}
                    error={
                      formik.touched.email &&
                      (!validateEmail(formik.values.email || '') ||
                        formik.values.email?.length === 0)
                    }
                    helperText={
                      formik.touched.email &&
                      (!validateEmail(formik.values.email || '') ||
                        formik.values.email?.length === 0) && (
                        <span style={{ textTransform: 'none' }}>
                          Please enter valid email id.
                        </span>
                      )
                    }
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('branchManage:reloadLoginMobile')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('branchManage:reloadLoginMobile')}
                    size="small"
                    {...formik.getFieldProps('reloadLoginMobile')}
                    error={
                      formik.touched.reloadLoginMobile &&
                      !validateMobileNumber(
                        formik.values.reloadLoginMobile || ''
                      )
                    }
                    helperText={
                      formik.touched.reloadLoginMobile &&
                      !validateMobileNumber(
                        formik.values.reloadLoginMobile || ''
                      ) && (
                        <span style={{ textTransform: 'none' }}>
                          Mobile number should be 10 digits.
                        </span>
                      )
                    }
                    inputProps={{ maxLength: 10 }}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('branchManage:reloadLoginPassword')} />
                  <TextField
                    autoComplete="off"
                    inputProps={{ autoComplete: 'new-password' }}
                    placeholder={t('branchManage:reloadLoginPassword')}
                    size="small"
                    type={showPassword ? 'text' : 'password'}
                    {...formik.getFieldProps('reloadLoginPassword')}
                    InputProps={{
                      endAdornment: (
                        <InputAdornment position="end">
                          <IconButton
                            edge="end"
                            onClick={() => setShowPassword(!showPassword)}
                          >
                            {showPassword ? <VisibilityOff /> : <Visibility />}
                          </IconButton>
                        </InputAdornment>
                      ),
                    }}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('branchManage:headerText1')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('branchManage:headerText1')}
                    size="small"
                    {...formik.getFieldProps('headerText1')}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('branchManage:headerText2')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('branchManage:headerText2')}
                    size="small"
                    {...formik.getFieldProps('headerText2')}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('branchManage:headerText3')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('branchManage:headerText3')}
                    size="small"
                    {...formik.getFieldProps('headerText3')}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('branchManage:footerText1')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('branchManage:footerText1')}
                    size="small"
                    {...formik.getFieldProps('footerText1')}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('branchManage:footerText2')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('branchManage:footerText2')}
                    size="small"
                    {...formik.getFieldProps('footerText2')}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('branchManage:footerText3')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('branchManage:footerText3')}
                    size="small"
                    {...formik.getFieldProps('footerText3')}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>

                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('branchManage:printPaperSize')} />
                  <TextField
                    select
                    size="small"
                    {...formik.getFieldProps('printPaperSize')}
                    sx={{ width: '100%' }}
                  >
                    {printPaperSizeOptions.map((option) => (
                      <MenuItem
                        key={option.value}
                        value={option.value}
                      >
                        {option.key}
                      </MenuItem>
                    ))}
                  </TextField>
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('branchManage:noticeText')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('branchManage:noticeText')}
                    size="small"
                    {...formik.getFieldProps('noticeText')}
                    sx={{ width: '100%' }}
                  />
                </GridItem>

                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('branchManage:totalCount')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('branchManage:totalCount')}
                    size="small"
                    type="number"
                    inputProps={{ step: 'any' }}
                    {...formik.getFieldProps('totalCount')}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>

                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('category:title.upload image')} />
                  <Box
                    sx={{
                      border: '2px dashed #cccccc',
                      borderRadius: '8px',
                      padding: '16px',
                      display: 'flex',
                      flexDirection: 'column',
                      alignItems: 'center',
                      justifyContent: 'center',
                      height: '200px',
                    }}
                  >
                    <Grid
                      container
                      spacing={2}
                    >
                      <Grid
                        item
                        xs={8}
                      >
                        {selectedImage && (
                          <img
                            alt="Selected"
                            height="160px"
                            src={URL.createObjectURL(selectedImage)}
                            style={{ position: 'inherit' }}
                            width="80%"
                          />
                        )}
                        {!selectedImage && branchdata && (
                          <img
                            alt="Selected"
                            height="160px"
                            src={branchdata.logo}
                            style={{ position: 'inherit' }}
                            width="80%"
                          />
                        )}
                      </Grid>
                      <Grid
                        item
                        xs={4}
                      >
                        <TextField
                          onChange={handleImageChange}
                          type="file"
                        />
                        {isImageUploading && (
                          <Box sx={{ pr: 2, pt: 0.5 }}>
                            <CircularProgress
                              size={16}
                              sx={{ color: 'white' }}
                            />
                          </Box>
                        )}
                      </Grid>
                    </Grid>
                  </Box>
                </GridItem>
              </Grid>
            </Box>
          </DialogContent>
          <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
            <Button
              onClick={handleClose}
              sx={{ borderColor: '#CBD5E1', borderRadius: '8px', color: '#475569', fontWeight: 600, height: 40, minWidth: 110, px: 3, textTransform: 'none', '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' } }}
              variant="outlined"
            >
              {t('common:cancel')}
            </Button>
            <Button
              autoFocus
              disabled={
                !formValid ||
                // Object.keys(formik.touched).length === 0 ||
                isLoading
              }
              onClick={() => {
                formik.handleSubmit();
              }}
              sx={{ background: HEADER_GRADIENT, borderRadius: '8px', boxShadow: '0 4px 14px rgba(15,29,77,0.25)', color: '#fff', fontWeight: 700, height: 40, minWidth: 110, px: 3, textTransform: 'none', '&:hover': { opacity: 0.9 }, '&.Mui-disabled': { background: '#CBD5E1', color: '#94A3B8', boxShadow: 'none' } }}
              type="submit"
              variant="contained"
            >
              {isLoading && (
                <Box sx={{ pr: 2, pt: 0.5 }}>
                  <CircularProgress
                    size={16}
                    sx={{ color: 'white' }}
                  />
                </Box>
              )}
              {buttonText}
            </Button>
          </DialogActions>
        </Dialog>
      </form>
    </div>
  );
};

export default React.memo(NewBranch);

const GridItem = ({ ...rest }) => {
  return (
    <Grid
      item
      key={1}
      lg={12}
      sm={12}
      xs={12}
      {...rest}
    />
  );
};
