import React, { CSSProperties, useMemo, useState } from 'react';
import {
  PaginationState,
  Row,
  getCoreRowModel,
  useReactTable,
} from '@tanstack/react-table';
import {
  IBranchDetails,
  IBranchDetailsData,
} from '../../core/Interface/branch.interface';
import usePageQuery from '../../core/hooks/usePageQuery';
import { useGetAllBranchQuery } from '../posApi';
import useBranchListColumn from './useBranchListColumn';

const useBranchList = (
  handleEdit: (data: IBranchDetailsData) => void,
  handleDelete: (data: IBranchDetailsData) => void,
  viewBranchDetailsPopUp: (id: string) => void
) => {
  const { page } = usePageQuery();
  const [popUpBranchId, setPopUpBranchId] = useState<string>('');
  const [pagination, setPagination] = React.useState<PaginationState>({
    pageIndex: page,
    pageSize: 10,
  });
  const [searchText, setSearchText] = useState('');

  const {
    data,
    isLoading,
    isFetching,
    error: fetchError,
  } = useGetAllBranchQuery({
    pageIndex: pagination.pageIndex,
    pageSize: pagination.pageSize,
    searchText,
  });

  const BranchList = useMemo(() => {
    return data?.data as IBranchDetails;
  }, [data?.data]);

  const [searchQuery, setSearchQuery] = useState('');
  const filteredBranchList = useMemo(() => {
    const query = searchQuery.toLowerCase().trim();
    return BranchList?.records.filter((value) => {
      const categoryName = value.name.toLowerCase();
      const categoryCode = value.mobile.toLowerCase();
      return categoryName.includes(query) || categoryCode.includes(query);
    });
  }, [BranchList, searchQuery]);

  const columns = useBranchListColumn({
    handleEdit,
    handleDelete,
    viewBranchDetailsPopUp,
  });

  const table = useReactTable({
    data: fetchError ? [] : filteredBranchList,
    columns: columns,
    initialState: {
      columnVisibility: {
        id: false,
      },
    },
    meta: {
      getRowStyles: (row: Row<IBranchDetailsData>): CSSProperties => ({}),
    },
    pageCount: BranchList?.totalRecords ?? 0,
    state: {
      pagination,
    },
    onPaginationChange: setPagination,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
  });

  return {
    table,
    isLoading: isFetching || isLoading,
    isInitLoading: isLoading,
    error: fetchError,
    totalCount: BranchList?.totalRecords ?? 0,
    popUpBranchId,
    searchText,
    setSearchText,
    setPopUpBranchId,
    setSearchQuery,
  };
};

export default useBranchList;
