import React, { useState } from 'react';
import {
  Box,
  Button,
  Chip,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  IconButton,
  Stack,
  Tooltip,
  Typography,
  useMediaQuery,
} from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import ScienceOutlinedIcon from '@mui/icons-material/ScienceOutlined';
import LocalGroceryStoreOutlinedIcon from '@mui/icons-material/LocalGroceryStoreOutlined';
import RestaurantOutlinedIcon from '@mui/icons-material/RestaurantOutlined';
import MenuBookOutlinedIcon from '@mui/icons-material/MenuBookOutlined';
import CheckroomOutlinedIcon from '@mui/icons-material/CheckroomOutlined';
import LocalCafeOutlinedIcon from '@mui/icons-material/LocalCafeOutlined';
import HardwareOutlinedIcon from '@mui/icons-material/HardwareOutlined';
import StorefrontOutlinedIcon from '@mui/icons-material/StorefrontOutlined';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';
import AddIcon from '@mui/icons-material/Add';
import RestartAltIcon from '@mui/icons-material/RestartAlt';
import { theme } from '../../../theme';
import { HEADER_GRADIENT } from '../../../theme/appColors';
import { useNotifier } from '../../../core/Notifier';
import { useGetDemoBranchesQuery, useGetDemoBusinessTypesQuery, useSetupDemoBranchMutation } from '../../posApi';
import { IDemoBranch, IDemoBusinessType, IDemoSetupResult } from '../../../core/Interface/branch.interface';

const BUSINESS_ICONS: Record<string, React.ElementType> = {
  Supermarket: LocalGroceryStoreOutlinedIcon,
  Restaurant: RestaurantOutlinedIcon,
  Bookshop: MenuBookOutlinedIcon,
  TextileShop: CheckroomOutlinedIcon,
  CoffeeShop: LocalCafeOutlinedIcon,
  HardwareShop: HardwareOutlinedIcon,
};

const toLabel = (key: string) => key.replace(/([a-z])([A-Z])/g, '$1 $2');

interface DemoBranchesProps {
  open: boolean;
  onClose: () => void;
}

const DemoBranches = ({ open, onClose }: DemoBranchesProps) => {
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const { showMessage, showErrorMessage } = useNotifier();
  const [busyKey, setBusyKey] = useState<string | null>(null);
  const [confirmResetKey, setConfirmResetKey] = useState<string | null>(null);

  const { data: typesData, isLoading: typesLoading } = useGetDemoBusinessTypesQuery();
  const { data: branchesData, isLoading: branchesLoading } = useGetDemoBranchesQuery();
  const [setupDemoBranch] = useSetupDemoBranchMutation();

  const businessTypes = (typesData?.status ? typesData.data : []) as IDemoBusinessType[];
  const demoBranches = (branchesData?.status ? branchesData.data : []) as IDemoBranch[];

  const handleSetup = async (key: string) => {
    setConfirmResetKey(null);
    setBusyKey(key);
    try {
      const response = await setupDemoBranch(key).unwrap();
      if (response.status) {
        const result = response.data as IDemoSetupResult;
        showMessage(`${response.message} — login: ${result.username}`);
      } else {
        showErrorMessage(response.message);
      }
    } catch (error) {
      const err = error as { data?: { message?: string }; message?: string };
      showErrorMessage(err.data?.message || err.message || 'Failed to set up demo branch');
    } finally {
      setBusyKey(null);
    }
  };

  const copyUsername = (username: string) => {
    navigator.clipboard?.writeText(username);
    showMessage(`Copied "${username}"`);
  };

  return (
    <Dialog fullScreen={isMobile} fullWidth maxWidth="sm" onClose={onClose} open={open}>
      {/* Header */}
      <Box sx={{ alignItems: 'center', background: HEADER_GRADIENT, display: 'flex', gap: 1.5, px: 3, py: 2 }}>
        <Box
          sx={{
            alignItems: 'center',
            background: 'rgba(255,255,255,0.15)',
            borderRadius: '10px',
            display: 'flex',
            height: 40,
            justifyContent: 'center',
            width: 40,
          }}
        >
          <ScienceOutlinedIcon sx={{ color: '#fff', fontSize: 22 }} />
        </Box>
        <Box sx={{ flex: 1 }}>
          <Typography sx={{ color: '#fff', fontSize: 18, fontWeight: 800, lineHeight: 1.2 }}>Demo Branches</Typography>
          <Typography sx={{ color: 'rgba(255,255,255,0.65)', fontSize: 12, fontWeight: 500 }}>
            Create a demo branch with sample data, or reset one to its original state
          </Typography>
        </Box>
        <IconButton onClick={onClose} size="small" sx={{ color: 'rgba(255,255,255,0.8)' }}>
          <CloseIcon fontSize="small" />
        </IconButton>
      </Box>

      <DialogContent sx={{ backgroundColor: '#F8FAFC', p: 2 }}>
        {typesLoading || branchesLoading ? (
          <Box sx={{ display: 'flex', justifyContent: 'center', py: 6 }}>
            <CircularProgress size={32} />
          </Box>
        ) : (
          <Stack spacing={1.25}>
            {businessTypes.map((type) => {
              const existing = demoBranches.find((b) => b.code === type.branchCode);
              const Icon = BUSINESS_ICONS[type.key] ?? StorefrontOutlinedIcon;
              const isBusy = busyKey === type.key;
              const isConfirming = confirmResetKey === type.key;

              return (
                <Box
                  key={type.key}
                  sx={{
                    alignItems: 'center',
                    backgroundColor: '#fff',
                    border: '1px solid',
                    borderColor: existing ? 'rgba(22,163,74,0.25)' : '#E2E8F0',
                    borderRadius: 2,
                    display: 'flex',
                    flexWrap: 'wrap',
                    gap: 1.5,
                    px: 2,
                    py: 1.5,
                  }}
                >
                  <Box
                    sx={{
                      alignItems: 'center',
                      backgroundColor: existing ? 'rgba(22,163,74,0.08)' : 'rgba(37,99,235,0.08)',
                      borderRadius: '10px',
                      color: existing ? '#16A34A' : '#2563EB',
                      display: 'flex',
                      flexShrink: 0,
                      height: 42,
                      justifyContent: 'center',
                      width: 42,
                    }}
                  >
                    <Icon />
                  </Box>

                  <Box sx={{ flex: 1, minWidth: 160 }}>
                    <Stack alignItems="center" direction="row" spacing={1}>
                      <Typography sx={{ color: '#0F172A', fontSize: 14, fontWeight: 700 }}>
                        {toLabel(type.key)}
                      </Typography>
                      {existing && (
                        <Chip
                          label="Active"
                          size="small"
                          sx={{ backgroundColor: 'rgba(22,163,74,0.1)', color: '#16A34A', fontSize: 11, fontWeight: 600, height: 20 }}
                        />
                      )}
                    </Stack>
                    <Typography sx={{ color: '#64748B', fontSize: 12 }}>
                      {type.branchName} · {type.branchCode}
                    </Typography>
                    {existing && (
                      <Stack alignItems="center" direction="row" spacing={0.5}>
                        <Typography sx={{ color: '#475569', fontSize: 12 }}>
                          Login: <b>{existing.username}</b>
                        </Typography>
                        <Tooltip title="Copy username">
                          <IconButton onClick={() => copyUsername(existing.username)} size="small" sx={{ p: 0.25 }}>
                            <ContentCopyIcon sx={{ fontSize: 13 }} />
                          </IconButton>
                        </Tooltip>
                      </Stack>
                    )}
                  </Box>

                  {isConfirming ? (
                    <Stack direction="row" spacing={1}>
                      <Button onClick={() => setConfirmResetKey(null)} size="small" sx={{ textTransform: 'none' }}>
                        Cancel
                      </Button>
                      <Button
                        color="error"
                        onClick={() => handleSetup(type.key)}
                        size="small"
                        sx={{ textTransform: 'none', fontWeight: 600 }}
                        variant="contained"
                      >
                        Confirm reset
                      </Button>
                    </Stack>
                  ) : (
                    <Button
                      disabled={!!busyKey}
                      onClick={() => (existing ? setConfirmResetKey(type.key) : handleSetup(type.key))}
                      size="small"
                      startIcon={isBusy ? <CircularProgress color="inherit" size={14} /> : existing ? <RestartAltIcon /> : <AddIcon />}
                      sx={{ borderRadius: '8px', fontWeight: 600, minWidth: 96, textTransform: 'none' }}
                      variant={existing ? 'outlined' : 'contained'}
                    >
                      {isBusy ? (existing ? 'Resetting' : 'Creating') : existing ? 'Reset' : 'Create'}
                    </Button>
                  )}

                  {isConfirming && (
                    <Typography sx={{ color: '#B91C1C', fontSize: 12, width: '100%' }}>
                      All data in {type.branchName} will be replaced with the original sample data.
                    </Typography>
                  )}
                </Box>
              );
            })}
          </Stack>
        )}
      </DialogContent>

      <DialogActions sx={{ px: 3, py: 1.5 }}>
        <Typography sx={{ color: '#94A3B8', flex: 1, fontSize: 11.5 }}>
          Demo users sign in with the configured demo password.
        </Typography>
        <Button onClick={onClose} sx={{ textTransform: 'none' }}>
          Close
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default DemoBranches;
